fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine the number of participants to consider: min(n, participations.len())
    let length = n.min(participations.len() as u8) as usize;

    // Count how many participants are eligible
    // Eligible if (5 - attendance_count) >= k
    let eligible_count = participations
        .iter()
        .take(length)
        .filter(|&&attendance| 5u8.saturating_sub(attendance) >= k)
        .count() as u8;

    // Maximum number of teams is eligible_count divided by 3 (integer division)
    eligible_count / 3
}